// No name heuristics or guessed replacement for an unmapped Wrath liquid.
inline const Profile* Resolve(uint32_t wrathType, bool& interior) {
    interior = false;
    for (const auto& mapping : kMappings) {
        if (mapping.wrathType != wrathType) continue;
        for (const auto& profile : kProfiles) {
            if (profile.id == mapping.foreverType) { interior = mapping.interior; return &profile; }
        }
        return nullptr;
    }
    return nullptr;
}
inline bool FoamTexturesFor(uint32_t profile, uint32_t& depth, uint32_t& rim) {
    for (const auto& mapping : kFoamTextureMappings) {
        if (mapping.profile == profile) { depth = mapping.depthFoamFileDataId; rim = mapping.rimFoamFileDataId; return true; }
    }
    depth = rim = 0; return false;
}
